class MyClass {
public:
  MyClass(int a, int b) : x(a), y(x + b) {} // Potential problem: y depends on x
  MyClass(int a, int b) : x(a) {y = x + b;} // Correct: initialization within constructor body
private:
  int x;
  int y;
};

code_example:
#include <iostream>
class MyClass {
public:
  MyClass(int a, int b) : x(a), y(x + b) {std::cout << "x: " << x << ", y: " << y << std::endl;}
  MyClass(int a, int b) : x(a) {y = x + b; std::cout << "x: " << x << ", y: " << y << std::endl;}
private:
  int x;
  int y;
};
int main() {
  MyClass obj1(5, 3); //Potentially problematic initialization
  MyClass obj2(5, 3); //Correct initialization
  return 0;
}
